// C1.9/D-8: without Authorization header → 401 ; per-user rate limit 60 req/min (sliding window, ORCE memory).
// msg._skip = true → the next switch short-circuits to the error response.
const auth = msg.req && msg.req.headers['authorization'];
function dspErr(status, code, reasons) {
  msg.statusCode = status;
  msg.payload = { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': reasons };
  msg.headers = { 'Content-Type': 'application/json' };
  msg._skip = true;
  return msg;
}
if (!auth) return dspErr(401, 'missing_credentials', ['Authorization: Bearer/DPoP required (OIDC session)']);
const key = crypto.createHash('sha256').update(auth).digest('hex').slice(0, 16);
const now = Date.now();
const win = (global.get('appquery_rl') || {});
const arr = (win[key] || []).filter(t => now - t < 60000);
if (arr.length >= 60) return dspErr(429, 'rate_limit_exceeded', ['60 req/min per user exceeded']);
arr.push(now); win[key] = arr; global.set('appquery_rl', win);
// original /app/query body (the userinfo response overwrites msg.payload afterwards)
msg._origBody = msg.payload;
msg._token = auth;
// prepare the IdP userinfo call (internal, docker network) with the presented token
msg.url = env.get('IDP_USERINFO_URL');
msg.method = 'GET';
msg.headers = { 'Authorization': auth };
return msg;

// C1.9: valid session (userinfo 200) + PDP check BEFORE signing — the proxy never bypasses control.
// v1: internal members (claim org == FAP_ORG) → internal framework contract DSP_AGREEMENT_ID (fap-ldp spec §7.1).
// Then canonical-form HMAC signature D-3 with DSP_HMAC_SECRET — never client-side (front spec §13.1).
function dspErr(status, code, reasons) {
  msg.statusCode = status;
  msg.payload = { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': reasons };
  msg.headers = { 'Content-Type': 'application/json' };
  msg._skip = true;
  return msg;
}
if (msg.statusCode !== 200 || !msg.payload || !msg.payload.webid) {
  return dspErr(401, 'invalid_session', ['invalid OIDC session']);
}
const claims = msg.payload;
const org = env.get('FAP_ORG') || 'fap-pod';
if (claims.org !== org) {
  return dspErr(403, 'forbidden', ['claim org=' + claims.org + ' != ' + org + ' : no internal framework contract']);
}
const orig = msg._origBody || {};
const assetId = orig.assetId, from = orig.from, to = orig.to;
if (!assetId || !from || !to) {
  return dspErr(400, 'invalid_request', ['body {assetId, from, to} required (from/to ISO 8601)']);
}
const secret = env.get('DSP_HMAC_SECRET') || '';
const agreement = env.get('DSP_AGREEMENT_ID') || '';
const path = env.get('DSP_DATA_PATH') || '/dsp/data';
const ts = new Date().toISOString();
const canonical = ['POST', path, assetId, from, to, ts].join('\n');
const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(canonical).digest('hex');
msg._audit = { agreement_id: agreement, asset_id: assetId, webid: claims.webid, role: claims.role };
msg.url = 'http://localhost:1880' + path;
msg.method = 'POST';
msg.headers = {
  'Content-Type': 'application/json',
  'X-DSP-Signature': sig,
  'X-DSP-Agreement': agreement,
  'X-DSP-Timestamp': ts,
  'Authorization': 'VC ' + (claims.webid || '')   // VC header only, never in the query string (RG-6)
};
msg.payload = { assetId: assetId, from: from, to: to };
return msg;

// C1.9: every call is audited (agreement_id, webid, asset, ts). The data plane response
// ({assetId, schema, table, columns, rows, rowCount} or dspace:Error) is returned as-is.
const { Pool } = pgLib;
const p = new Pool({ connectionString: env.get('PG_ADMIN_DSN') });
const a = msg._audit || {};
const status = msg.statusCode || 200;
p.query('INSERT INTO public.dsp_access_audit (agreement_id, asset_id, ts, status, path) VALUES ($1,$2,now(),$3,$4)',
  [a.agreement_id || '', a.asset_id || '', status, '/app/query'])
  .catch(e => node.warn('audit /app/query: ' + e.message))
  .finally(() => p.end());
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// RG-3 (fap-ldp spec §5.3): no direct write from the app into bronze/silver/gold.
// The outbox (trigger app.outbox_trigger + pg_notify('fap_ingest')) is consumed here:
// each event goes to bronze via public.gate_ingest() with the gate role (INSERT bronze only).
// Polling implementation every 30 s (pg_notify listener = future optimization).
const { Pool } = pgLib;
const appPool = new Pool({ connectionString: env.get('PG_APP_DSN') });
const gatePool = new Pool({ connectionString: env.get('PG_GATE_DSN') });
(async () => {
  try {
    const rs = await appPool.query(
      'SELECT id, event_type, payload FROM app.outbox WHERE processed_at IS NULL ORDER BY id LIMIT 100');
    for (const row of rs.rows) {
      try {
        await gatePool.query(
          "SELECT public.gate_ingest('app.event', $1::jsonb, 'app-supervision/outbox', 'app', $2)",
          [JSON.stringify(row.payload), 'outbox/' + row.id]);
        await appPool.query('UPDATE app.outbox SET processed_at = now() WHERE id = $1', [row.id]);
      } catch (e) {
        node.warn('outbox id=' + row.id + ' failed (retry next cycle): ' + e.message);
      }
    }
  } catch (e) {
    node.error('outbox: ' + e.message, msg);
  } finally {
    appPool.end(); gatePool.end();
  }
  node.done();
})();
return null;

// CR-5 (app-store-catalogue spec §2/§4.6): LLM endpoint POST /app/llm — a FUNCTION, not a
// data resource. OIDC session auth (userinfo), rate limit 10 req/min/user (sliding
// window, ORCE memory), audit dsp.audit. The requested data is read OVER LDP (container
// published, CR-0) via the internal PEP with the user's token → ACL/RLS enforced.
function dspErr(status, code, reasons) {
  msg.statusCode = status;
  msg.payload = { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': reasons };
  msg.headers = { 'Content-Type': 'application/json' };
  msg._skip = true;
  return msg;
}
const auth = msg.req && msg.req.headers['authorization'];
if (!auth) return dspErr(401, 'missing_credentials', ['Authorization: Bearer/DPoP required (OIDC session)']);
const key = crypto.createHash('sha256').update(auth).digest('hex').slice(0, 16);
const now = Date.now();
const win = (global.get('appllm_rl') || {});
const arr = (win[key] || []).filter(t => now - t < 60000);
if (arr.length >= 10) return dspErr(429, 'rate_limit_exceeded', ['10 req/min per user exceeded (CR-5)']);
arr.push(now); win[key] = arr; global.set('appllm_rl', win);
msg._origBody = msg.payload;
msg._token = auth;
msg.url = env.get('IDP_USERINFO_URL');
msg.method = 'GET';
msg.headers = { 'Authorization': auth };
return msg;

// CR-5: valid session (userinfo 200) then server-side asset whitelist (gold containers
// published LDP — CR-0). Never all of gold without ACL. The payload becomes the list of assets
// to read (split). NO async here (the ORCE runtime does not return main to async function nodes
// of HTTP flows): reading happens node by node (split → http request → join).
function dspErr(status, code, reasons) {
  msg.statusCode = status;
  msg.payload = { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': reasons };
  msg.headers = { 'Content-Type': 'application/json' };
  msg._skip = true;
  return msg;
}
if (msg.statusCode !== 200 || !msg.payload || !msg.payload.webid) {
  return dspErr(401, 'invalid_session', ['invalid OIDC session']);
}
const claims = msg.payload;
const body = msg._origBody || {};
const assets = Array.isArray(body.assets) ? body.assets : [];
const prompt = String(body.prompt || '');
if (!prompt) return dspErr(400, 'invalid_request', ['body {assets: [...], prompt, model?} required']);
const whitelist = (env.get('LLM_ASSETS') || '/gold/anomaly_candidates/,/gold/city_dashboard_summary/,/gold/energy_balance_hourly/,/gold/energy_cost_daily/,/gold/event_impact_daily/,/gold/intervention_anomaly_daily/,/gold/net_grid_hourly/,/gold/pv_performance_hourly/,/gold/streetlight_zone_hourly/,/gold/weather_hourly/,/gold/price_hourly/,/gold/city_event_hourly/,/gold/annual_site_consumption/').split(',').map(s => s.trim()).filter(Boolean);
const wanted = assets.filter(a => whitelist.indexOf(a) >= 0);
const rejected = assets.filter(a => whitelist.indexOf(a) < 0);
if (rejected.length) return dspErr(403, 'forbidden', ['assets outside the server whitelist: ' + rejected.join(', ')]);
if (!wanted.length) return dspErr(400, 'invalid_request', ['no authorized asset in the request']);
msg._llm = { webid: claims.webid, prompt: prompt, model: body.model || 'default', assets: wanted };
msg.payload = wanted;   // → split
return msg;

// The requested asset is read OVER LDP, internally (same runtime), with the user's token:
// the PEP enforces ACL/RLS — the endpoint never sees more than what the user can read.
msg._asset = String(msg.payload);
msg.url = 'http://localhost:1880' + msg._asset;
msg.method = 'GET';
msg.headers = { 'Authorization': msg._token, 'Accept': 'application/ld+json' };
msg.payload = null;
return msg;

// CR-5: audit of each call (dsp.audit, fire-and-forget like /app/query), then assembling
// of the context from the LDP containers read. Without LLM_ENDPOINT → 503 llm_not_configured.
// With LLM_ENDPOINT → prepare the LLM call (next node).
const { Pool } = pgLib;
const p = new Pool({ connectionString: env.get('PG_ADMIN_DSN') });
const llm = msg._llm || {};
p.query('INSERT INTO dsp.audit (agreement_id, webid, resource_uri, mode, decision) VALUES ($1,$2,$3,$4,$5)',
  [env.get('DSP_AGREEMENT_ID') || '', llm.webid || '', '/app/llm', 'llm', 'allow'])
  .catch(e => node.warn('audit /app/llm: ' + e.message))
  .finally(() => p.end());
// join auto mode: msg.payload = array of payloads (the LDP documents read)
const parts = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
const ctx = parts.map(r => ({
  asset: r && r['@id'],
  members: r && r['ldp:contains'] ? r['ldp:contains'].length : 0
}));
const endpoint = env.get('LLM_ENDPOINT') || '';
if (!endpoint) {
  msg.statusCode = 503;
  msg.payload = { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error',
    'dspace:code': 'llm_not_configured',
    'dspace:reason': ['LLM_ENDPOINT not configured server-side — assets read over LDP: ' + (llm.assets || []).join(', ')],
    assetsRead: llm.assets || [], context: ctx };
  msg.headers = { 'Content-Type': 'application/json' };
  msg._skip = true;
  return msg;
}
msg.url = endpoint;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
if (env.get('LLM_API_KEY')) msg.headers['Authorization'] = 'Bearer ' + env.get('LLM_API_KEY');
msg.payload = { model: llm.model, prompt: llm.prompt, context: ctx };
return msg;
